import 'package:visaia/services/firestore_safe_ext.dart';
import 'package:cloud_firestore/cloud_firestore.dart';
import 'package:visaia/services/local_write_service.dart';

String formatCycleName({
  required String crop,
  required String variety,
  required bool isPrevious,
  required int number,
}) => isPrevious
    ? '$crop ($variety) - Prev Cycle $number'
    : '$crop ($variety) - Cycle $number | New';

/// Retire the newest marker, including names generated by older app versions.
String retireNewCycleName(String name) => name
    .replaceFirst(RegExp(r' \| New$'), '')
    .replaceFirst(RegExp(r' - New Cycle (?=[0-9]+$)'), ' - Cycle ');

int nextCycleNumber(
  Iterable<Map<String, dynamic>> cycles, {
  required bool isPrevious,
}) {
  var count = 0;
  var highest = 0;
  final suffix = RegExp(r' - (?:(New|Prev) )?Cycle ([0-9]+)(?: \| New)?$');
  for (final cycle in cycles) {
    final name = (cycle['cycleName'] ?? '').toString();
    final match = suffix.firstMatch(name);
    final previous =
        cycle['isPreviousCycle'] == true ||
        match?.group(1) == 'Prev' ||
        name.startsWith('Prev. Cycle |');
    if (previous != isPrevious) continue;
    count++;
    final number = int.tryParse(match?.group(2) ?? '') ?? 0;
    if (number > highest) highest = number;
  }
  return (highest > count ? highest : count) + 1;
}

class CycleNamingService {
  /// Commit the new cycle and retiring names together, including offline writes.
  Future<void> createCycle({
    required String userId,
    required String farmId,
    required Map<String, dynamic> data,
    required bool useAutoName,
  }) async {
    final collection = FirebaseFirestore.instance
        .collection('users')
        .doc(userId)
        .collection('cycles');
    final cycles = await collection
        .where('farmId', isEqualTo: farmId)
        .safeGet();
    final batch = FirebaseFirestore.instance.batch();
    for (final doc in cycles.docs) {
      final existing = doc.data();
      if (existing['isPreviousCycle'] == true) continue;
      final name = (existing['cycleName'] ?? '').toString();
      final retired = retireNewCycleName(name);
      if (retired != name) batch.update(doc.reference, {'cycleName': retired});
    }
    final ref = collection.doc();
    batch.set(ref, {
      ...data,
      if (useAutoName)
        'cycleName': formatCycleName(
          crop: data['cropType'] as String,
          variety: data['cropVariety'] as String,
          isPrevious: false,
          number: nextCycleNumber(
            cycles.docs.map((doc) => doc.data()),
            isPrevious: false,
          ),
        ),
    });
    await LocalWriteService.run(ref, batch.commit);
  }

  Future<int> nextNumber({
    required String userId,
    required String farmId,
    required bool isPrevious,
  }) async {
    final cycles = await FirebaseFirestore.instance
        .collection('users')
        .doc(userId)
        .collection('cycles')
        .where('farmId', isEqualTo: farmId)
        .safeGet();
    return nextCycleNumber(
      cycles.docs.map((doc) => doc.data()),
      isPrevious: isPrevious,
    );
  }
}
